mapper.update:
update t_erp_fin_account
set findex=#{findex,jdbcType=INTEGER}
where id=#{id,jdbcType=BIGINT}

mapper.select:
SELECT inv.materialid AS materialId, m.sku, m.name AS materialName, inv.warehouseid AS warehouseId, w.name AS warehouseName, IFNULL(m.price, 0) AS unitPrice, IFNULL(m.price_wavg, 0) AS avgPrice, IFNULL(SUM(inv.quantity), 0) AS totalQuantity, IFNULL(SUM(CASE WHEN substring_index(inv.status,'_',1) = 'fulfillable' THEN inv.quantity ELSE 0 END), 0) AS fulfillableQuantity, IFNULL(SUM(CASE WHEN substring_index(inv.status,'_',1) = 'inbound' THEN inv.quantity ELSE 0 END), 0) AS inboundQuantity, ROUND(IFNULL(SUM(inv.quantity), 0) * IFNULL(m.price_wavg, 0), 2) AS totalAmount FROM t_erp_inventory inv INNER JOIN t_erp_material m ON m.id = inv.materialid LEFT JOIN t_erp_warehouse w ON w.id = inv.warehouseid WHERE inv.shopid = #{param.shopid}
AND inv.materialid = #{param.materialId}
AND inv.warehouseid = #{param.warehouseId}
AND m.sku LIKE CONCAT('%', #{param.sku}, '%')
GROUP BY inv.materialid, m.sku, m.name, inv.warehouseid, w.name, m.price, m.price_wavg ORDER BY m.sku

mapper.sql:
WHERE rec.shopid = #{param.shopid}

  AND rec.materialid = #{param.materialId}


  AND rec.warehouseid = #{param.warehouseId}


  AND rec.formtype = #{param.formType}


  AND rec.opttime >= #{param.fromDate}


  AND rec.opttime <= #{param.toDate}

mapper.select:
SELECT rec.id, rec.materialid AS materialId, m.sku, m.name AS materialName, rec.warehouseid AS warehouseId, w.name AS warehouseName, rec.formtype AS formType, rec.number AS formNumber, rec.quantity AS quantityChange, rec.status AS inventoryStatus, rec.operate AS operateType, rec.opttime AS operateTime, u.name AS operator FROM t_erp_inventory_record rec INNER JOIN t_erp_material m ON m.id = rec.materialid LEFT JOIN t_erp_warehouse w ON w.id = rec.warehouseid LEFT JOIN t_userinfo u ON u.id = rec.operator
ORDER BY rec.opttime DESC
LIMIT #{param.offset}, #{param.pageSize}
